      <header class="page__header">
        <figure class="page__hero">
          <img
            v-if="project.hero && project.hero.src"
            class="page__hero-media"
            :src="project.hero.src"
            :alt="project.hero.alt"
          />
          <div
            v-else
            class="page__hero-frame"
            role="img"
            :aria-label="project.hero ? project.hero.alt : project.title"
          />
          <figcaption v-if="project.hero && project.hero.caption" class="page__hero-caption">
            {{ project.hero.caption }}
          </figcaption>
        </figure>
        <div class="page__intro">
          <div class="page__titles">
            <h1 class="page__title">{{ project.title }}</h1>
            <span v-if="project.status" class="page__status">{{
              project.status
            }}</span>
          </div>
          <p class="page__lede">{{ project.description }}</p>
          <ul
            v-if="project.tech_stack && project.tech_stack.length"
            class="page__stack"
          >
            <li v-for="(tech, i) in project.tech_stack" :key="i">{{ tech }}</li>
          </ul>
        </div>
      </header>

      <section v-if="project.overview && project.overview.length" class="block">
        <h2 class="block__title">Overview</h2>
        <SectionBlocks :items="project.overview" />
      </section>

      <section v-if="project.approach && project.approach.length" class="block">
        <h2 class="block__title">Approach</h2>
        <SectionBlocks :items="project.approach" />
      </section>

      <section v-if="project.results && project.results.length" class="block">
        <h2 class="block__title">Results</h2>
        <SectionBlocks :items="project.results" />
      </section>
    </div>
  </div>
  <div v-else class="page">
    <div class="page__inner">
      <p class="page__back">
        <router-link to="/#research">← Featured research and projects</router-link>
      </p>
      <h1 class="page__title">Project not found</h1>
      <p>That featured project does not exist.</p>
    </div>
  </div>
</template>

<script>
import SectionBlocks from '@/components/SectionBlocks.vue'
import { getFeaturedProject, isProjectDetailOpen } from '@/data/featuredProjects'

export default {
  name: 'ProjectDetail',
  components: {
    SectionBlocks
  },
  computed: {
    project () {
      const found = getFeaturedProject(this.$route.params.slug)
      return isProjectDetailOpen(found) ? found : null
    }
  },
  watch: {
    project: {
      immediate: true,
      handler (p) {
        document.title = p
          ? `${p.title} — Tobi Obadiah`
          : 'Project — Tobi Obadiah'
      }
    }
  }
}
</script>

