<template>
  <div class="chart" role="img" :aria-label="ariaLabel">
    <svg
      class="chart__svg"
      viewBox="0 0 720 360"
      xmlns="http://www.w3.org/2000/svg"
    >
      <text
        x="16"
        y="178"
        class="chart__axis-title"
        transform="rotate(-90 16 178)"
      >
        {{ yLabel }}
      </text>

      <line
        v-for="tick in ticks"
        :key="'g-' + tick.value"
        :x1="plot.left"
        :x2="plot.right"
        :y1="tick.y"
        :y2="tick.y"
        class="chart__grid"
      />

      <text
        v-for="tick in ticks"
        :key="'t-' + tick.value"
        :x="plot.left - 8"
        :y="tick.y + 4"
        class="chart__tick"
        text-anchor="end"
      >
        {{ tick.label }}
      </text>

      <g v-for="(cat, i) in categories" :key="cat">
        <rect
          v-for="(item, s) in series"
          :key="cat + '-' + item.name"
          :x="barX(i, s)"
          :y="barY(values[i][s])"
          :width="barWidth"
          :height="barHeight(values[i][s])"
          :fill="item.color"
          rx="2"
        >
          <title>
            {{ item.name }} {{ cat }}: {{ formatUs(values[i][s]) }}
          </title>
        </rect>
        <text
          :x="groupCenter(i)"
          :y="plot.bottom + 16"
          class="chart__cat"
          text-anchor="middle"
        >
          <tspan>{{ catLines(cat)[0] }}</tspan>
          <tspan
            v-if="catLines(cat)[1]"
            :x="groupCenter(i)"
            dy="12"
          >{{ catLines(cat)[1] }}</tspan>
        </text>
      </g>

      <line
        :x1="plot.left"
        :y1="plot.top"
        :x2="plot.left"
        :y2="plot.bottom"
        class="chart__axis"
      />
      <line
        :x1="plot.left"
        :y1="plot.bottom"
        :x2="plot.right"
        :y2="plot.bottom"
        class="chart__axis"
      />

      <g :transform="`translate(${plot.left}, 14)`">
        <g v-for="(item, s) in series" :key="'leg-' + item.name" :transform="`translate(${s * 88}, 0)`">
          <rect width="10" height="10" rx="1" :fill="item.color" y="-8" />
          <text x="16" y="1" class="chart__legend">{{ item.name }}</text>
        </g>
      </g>
    </svg>
  </div>
</template>

<script>
const PLOT = { left: 72, right: 700, top: 28, bottom: 312 }

export default {
  name: 'LogBarChart',
  props: {
    categories: {
      type: Array,
      required: true
    },
    values: {
      type: Array,
      required: true
    },
    series: {
      type: Array,
      required: true
    },
    yLabel: {
      type: String,
      default: 'µs (log)'
    },
    ariaLabel: {
      type: String,
      default: 'Log-scale bar chart'
    }
  },
  data () {
    return {
      plot: PLOT,
      logMin: 0,
      logMax: 4
    }
  },
  computed: {
    barWidth () {
      return 18
    },
    groupWidth () {
      return (PLOT.right - PLOT.left) / this.categories.length
    },
    ticks () {
      return [1, 10, 100, 1000, 10000].map((value) => ({
        value,
        label: this.formatTick(value),
        y: this.valueY(value)
      }))
    }
  },
  methods: {
    catLines (label) {
      if (label.startsWith('Node')) {
        return ['Node', label.slice(4)]
      }
      if (label.startsWith('Edge')) {
        return ['Edge', label.slice(4)]
      }
      return [label]
    },
    groupCenter (i) {
      return PLOT.left + this.groupWidth * (i + 0.5)
    },
    barX (i, s) {
      const pair = this.barWidth * 2 + 5
      return this.groupCenter(i) - pair / 2 + s * (this.barWidth + 5)
    },
    logT (value) {
      const v = Math.max(value, 1)
      return (Math.log10(v) - this.logMin) / (this.logMax - this.logMin)
    },
    valueY (value) {
      const h = PLOT.bottom - PLOT.top
      return PLOT.bottom - this.logT(value) * h
    },
    barY (value) {
      return this.valueY(value)
    },
    barHeight (value) {
      return PLOT.bottom - this.valueY(value)
    },
    formatTick (value) {
      if (value >= 1000) return `${value / 1000}k`
      return String(value)
    },
    formatUs (value) {
      const n = Number(value)
      if (n >= 1000) return `${n.toFixed(0)} µs`
      return `${n.toFixed(1)} µs`
    }
  }
}
</script>

