<template>
  <div class="blocks">
    <template v-for="(block, i) in items" :key="i">
      <p v-if="block.type === 'p'" class="blocks__p">{{ block.text }}</p>

      <h3 v-else-if="block.type === 'h3'" class="blocks__h3">{{ block.text }}</h3>

      <ul v-else-if="block.type === 'ul'" class="blocks__ul">
        <li v-for="(item, j) in block.items" :key="j">{{ item }}</li>
      </ul>

      <figure
        v-else-if="block.type === 'code'"
        class="blocks__code"
        :class="{ 'blocks__code--console': isConsole(block) }"
      >
        <figcaption v-if="block.caption" class="blocks__caption">
          {{ block.caption }}
        </figcaption>
        <div v-if="isConsole(block)" class="blocks__console">
          <div class="blocks__console-bar" aria-hidden="true">gdb_repl</div>
          <pre><code>{{ block.text }}</code></pre>
        </div>
        <pre v-else><code>{{ block.text }}</code></pre>
      </figure>

      <figure v-else-if="block.type === 'table'" class="blocks__table-wrap">
        <figcaption class="blocks__caption">{{ block.caption }}</figcaption>
        <div class="blocks__table-scroll">
          <table class="blocks__table">
            <thead>
              <tr>
                <th v-for="(h, j) in block.headers" :key="j">{{ h }}</th>
              </tr>
            </thead>
            <tbody>
              <tr v-for="(row, r) in block.rows" :key="r">
                <td v-for="(cell, c) in row" :key="c">{{ cell }}</td>
              </tr>
            </tbody>
          </table>
        </div>
        <p v-if="block.note" class="blocks__note">{{ block.note }}</p>
      </figure>

      <figure v-else-if="block.type === 'figure'" class="blocks__figure">
        <video
          v-if="block.src && block.kind === 'video'"
          class="blocks__media"
          :src="block.src"
          controls
          playsinline
          preload="metadata"
        />
        <img
          v-else-if="block.src"
          class="blocks__media"
          :class="{ 'blocks__media--white': block.surface === 'white' }"
          :src="block.src"
          :alt="block.alt"
          loading="lazy"
        />
        <div
          v-else
          class="blocks__frame"
          :class="{ 'blocks__frame--video': block.kind === 'video' }"
          role="img"
          :aria-label="block.alt"
        />
        <figcaption class="blocks__caption">{{ block.caption }}</figcaption>
      </figure>

      <figure v-else-if="block.type === 'chart'" class="blocks__figure">
        <figcaption class="blocks__caption">{{ block.caption }}</figcaption>
        <LogBarChart
          :categories="block.categories"
          :values="block.values"
          :series="block.series"
          :y-label="block.yLabel"
          :aria-label="block.alt || block.caption"
        />
      </figure>

      <p v-else-if="block.type === 'callout'" class="blocks__callout">
        {{ block.text }}
      </p>

      <div v-else-if="block.type === 'status-list'" class="status-list">
        <p v-if="block.intro" class="blocks__p">{{ block.intro }}</p>
        <ul class="status-list__legend" aria-hidden="true">
          <li><span class="status-dot status-dot--ready" /> Available</li>
          <li><span class="status-dot status-dot--developing" /> In development</li>
          <li><span class="status-dot status-dot--planned" /> Planned</li>
        </ul>
        <section
          v-for="group in block.groups"
          :key="group.status"
          class="status-list__group"
        >
          <h4 class="status-list__heading">{{ group.title }}</h4>
          <ul class="status-list__items">
            <li
              v-for="(item, j) in group.items"
              :key="j"
              class="status-list__item"
            >
              <span
                class="status-dot"
                :class="'status-dot--' + group.status"
                :title="group.title"
              />
              {{ item }}
            </li>
          </ul>
        </section>
      </div>
    </template>
  </div>
</template>

<script>
import LogBarChart from '@/components/LogBarChart.vue'

export default {
  name: 'SectionBlocks',
  components: {
    LogBarChart
  },
  props: {
    items: {
      type: Array,
      default: () => []
    }
  },
  methods: {
    isConsole(block) {
      const lang = (block.language || '').toLowerCase()
      return lang === 'console' || lang === 'bash' || lang === 'shell' || lang === 'sh'
    }
  }
}
